import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"审计与签名","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/audit.md","filePath":"modules/forge/audit.md","lastUpdated":0}`),a={name:`modules/forge/audit.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="审计与签名" tabindex="-1">审计与签名 <a class="header-anchor" href="#审计与签名" aria-label="Permalink to “审计与签名”">​</a></h1><p>Forge 在锻造成功后会向结果物品写入审计数据，用于追溯锻造来源和防篡改验证。</p><h2 id="数据落在哪里" tabindex="-1">数据落在哪里 <a class="header-anchor" href="#数据落在哪里" aria-label="Permalink to “数据落在哪里”">​</a></h2><p>锻造审计数据同时存在于两个位置：</p><ol><li><strong>CoreLib 物品层快照</strong>：namespace 为 <code>forge</code>，layer version 为 <code>1</code>，payload 就是下面的审计字段表（由 <code>ForgeLayerSnapshotBuilder</code> 组装）。刷新物品时从这里读回。</li><li><strong><code>emakiforge:forge</code> PDC 分区</strong>：把关键字段打成扁平键，供占位符与变量系统读取。见<a href="#锻造层-pdc-键">锻造层 PDC 键</a>。</li></ol><h2 id="审计字段" tabindex="-1">审计字段 <a class="header-anchor" href="#审计字段" aria-label="Permalink to “审计字段”">​</a></h2><p>锻造完成后，以下字段写入审计 payload：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>schema</code></td><td>审计结构标识，当前固定为 <code>forge_audit_v2</code>。</td></tr><tr><td><code>schema_version</code></td><td>审计结构版本，当前为 <code>2</code>。</td></tr><tr><td><code>stage</code></td><td>来源阶段，当前固定为 <code>forge</code>。</td></tr><tr><td><code>recipe_id</code></td><td>使用的配方 ID。</td></tr><tr><td><code>quality</code></td><td>品质等级名称；品质未解析时为空字符串。</td></tr><tr><td><code>multiplier</code></td><td>品质倍率。</td></tr><tr><td><code>forged_at</code></td><td>锻造时间戳（毫秒）。</td></tr><tr><td><code>materials_signature</code></td><td>材料贡献数据的稳定哈希签名。</td></tr><tr><td><code>output_item</code></td><td>输出物品来源简写。仅在配方配置了输出物品来源时写入。</td></tr><tr><td><code>materials</code></td><td>材料贡献列表，见下表。</td></tr></tbody></table><p><code>materials[]</code> 每个条目的字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>material_id</code> / <code>count_key</code> / <code>audit_id</code></td><td>材料身份键。仅在配置里显式声明过时写入；未声明时该键被移除。</td></tr><tr><td><code>material_item</code></td><td>兼容身份：物品源简写，或 <code>matcher:&lt;摘要&gt;</code>。</td></tr><tr><td><code>category</code></td><td>材料分类（必需 / 可选）。</td></tr><tr><td><code>amount</code></td><td>规划投入的数量。</td></tr><tr><td><code>amount_consumed</code></td><td>实际消耗的数量。</td></tr><tr><td><code>slot</code></td><td>材料所在的 GUI 槽位。</td></tr><tr><td><code>sequence</code></td><td>处理顺序。</td></tr><tr><td><code>matched_source</code></td><td>实际匹配到的物品源简写。</td></tr><tr><td><code>matcher</code></td><td>matcher 摘要键；没有 matcher 时为空字符串。</td></tr><tr><td><code>allocation</code></td><td>该条目的槽位分配明细。</td></tr><tr><td><code>legacy_identity</code> / <code>identity_diagnostic</code></td><td>存在未显式声明的身份键时补充的兼容身份与诊断标记。</td></tr></tbody></table><h2 id="材料签名" tabindex="-1">材料签名 <a class="header-anchor" href="#材料签名" aria-label="Permalink to “材料签名”">​</a></h2><p><code>materials_signature</code> 只对实际消耗数量大于 0 的材料贡献计算稳定哈希签名，签名输入包含材料定义摘要、数量、消耗量、槽位、分类、顺序、匹配来源与分配明细。相同的材料贡献组合总是得到相同签名，因此可以用于比对物品的锻造材料数据是否与预期一致。</p><h2 id="锻造层-pdc-键" tabindex="-1">锻造层 PDC 键 <a class="header-anchor" href="#锻造层-pdc-键" aria-label="Permalink to “锻造层 PDC 键”">​</a></h2><p>命名空间 <code>emakiforge</code>、分区 <code>forge</code> 下的扁平键：</p><table tabindex="0"><thead><tr><th>键</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>forge_recipe_id</code></td><td>string</td><td>锻造该物品的配方 ID。</td></tr><tr><td><code>quality_id</code></td><td>string</td><td>品质 ID（与品质名同值）。</td></tr><tr><td><code>quality_display</code></td><td>string</td><td>品质显示名。</td></tr><tr><td><code>quality_multiplier</code></td><td>string</td><td>品质倍率，按 <code>0.##</code> 格式化后存储。</td></tr><tr><td><code>material_id</code></td><td>string</td><td>显式声明的 <code>material_id</code> 列表，逗号连接；无则移除该键。</td></tr><tr><td><code>count_key</code></td><td>string</td><td>显式声明的 <code>count_key</code> 列表，逗号连接；无则移除该键。</td></tr><tr><td><code>audit_id</code></td><td>string</td><td>显式声明的 <code>audit_id</code> 列表，逗号连接；无则移除该键。</td></tr><tr><td><code>matched_source</code></td><td>string</td><td>匹配来源简写列表，逗号连接。</td></tr><tr><td><code>amount_consumed</code></td><td>integer</td><td>全部材料实际消耗量合计。</td></tr><tr><td><code>matcher_digest</code></td><td>string</td><td>matcher 摘要列表，逗号连接。</td></tr><tr><td><code>allocation</code></td><td>string</td><td>分配明细的稳定签名。</td></tr></tbody></table><p>这些键会被 CoreLib 变量系统读取为 <code>forge_quality_id</code>、<code>forge_quality_display</code>、<code>forge_quality_multiplier</code>、<code>forge_recipe_id</code> 四个变量。</p><h2 id="与刷新的关系" tabindex="-1">与刷新的关系 <a class="header-anchor" href="#与刷新的关系" aria-label="Permalink to “与刷新的关系”">​</a></h2><p>Forge 的物品刷新服务会读取审计数据中的 <code>recipe_id</code> 和 <code>quality</code>，据此重建锻造层展示。审计数据缺失、品质已不在当前品质池中，或配方已被删除时，对应物品无法重建锻造层展示并会打警告。</p><p>读取材料审计记录时，当前实现按 <code>audit_id</code> → <code>material_id</code> → <code>count_key</code> → 旧 <code>material_item</code> / <code>source</code> 依次回退。使用旧身份成功解析后会标记为需要迁移并在刷新时重建；身份全部无法解析时保留原物品并记录 warning，不会用不完整结果覆盖原状态。<strong>材料身份键必须保持稳定</strong>：纯 matcher 材料会按 matcher 内容摘要派生身份，改动 matcher 后旧成品会报「未找到材料」（<code>console.forge_refresh_missing_material</code>）。该行为已由源码证明，但本轮没有在真实 Paper/Folia 服务器上验证旧 PDC 审计数据。</p><h2 id="用途场景" tabindex="-1">用途场景 <a class="header-anchor" href="#用途场景" aria-label="Permalink to “用途场景”">​</a></h2><ul><li>交易或回收系统可读取审计数据判断物品的配方来源与品质。</li><li>外部统计可按 <code>recipe_id</code>、<code>quality</code> 和 <code>forged_at</code> 聚合锻造产出。</li></ul><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Forge 未提供查看审计数据的内置命令。需要人工查看时，请使用支持读取物品 PDC 与物品层快照的外部工具。</p></div>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};